### c++.2008 分数类运算符重载

### 注意！本题下方有提示 “分数的输出要求。。。最简形式” 这里即使分子为 0 时，输出仍然不可省略分母部分。。。即使分子等于分母，或者分子分母互为相反数，也只能输出 1/1 或者 -1/1，而不能输出 1 或者 -1。

这题被防了很久。。。我很无语

```c++
#include<iostream>
using namespace std;

//你提交的代码在这里
class Fraction {
public:
    int znum;
    int mnum;
    int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
    void yue() {
        if (mnum < 0) {
            znum *= -1;
            mnum *= -1;
        }
        int g = gcd(abs(znum), abs(mnum));
        znum /= g;
        mnum /= g;
        return;
    }
    Fraction operator+ (Fraction f) {
        Fraction tmp;
        tmp.mnum = this->mnum * f.mnum;
        tmp.znum = this->znum * f.mnum + this->mnum * f.znum;
        tmp.yue();
        return tmp;
    }
    Fraction operator- (Fraction f) {
        Fraction tmp;
        tmp.mnum = this->mnum * f.mnum;
        tmp.znum = this->znum * f.mnum - this->mnum * f.znum;
        tmp.yue();
        return tmp;
    }
    Fraction operator* (Fraction f) {
        Fraction tmp = *this;
        tmp.znum *= f.znum;
        tmp.mnum *= f.mnum;
        tmp.yue();
        return tmp;
    }
    Fraction operator/ (Fraction f) {
        Fraction tmp = *this;
        tmp.znum *= f.mnum;
        tmp.mnum *= f.znum;
        tmp.yue();
        return tmp;
    }
};
istream& operator>> (istream& cin, Fraction& s) {
    cin >> s.znum >> s.mnum;
    s.yue();
    return cin;
}
ostream& operator<< (ostream& cout, Fraction& s) {
    cout << s.znum << "/" << s.mnum;
    return cout;
}

int main()
{
    Fraction f1,f2,f3;
    cin>>f1>>f2;
    f3=f1+f2;
    cout<<f1<<" + "<<f2<<" = "<<f3<<endl;
    f3=f1-f2;
    cout<<f1<<" - "<<f2<<" = "<<f3<<endl;
    f3=f1*f2;
    cout<<f1<<" * "<<f2<<" = "<<f3<<endl;
    f3=f1/f2;
    cout<<f1<<" / "<<f2<<" = "<<f3<<endl;
