## 欧拉图

    具有欧拉回路的图就是欧拉图

    如果图中的一个路径包含几个边恰好一次，该路径就是欧拉路径

    如果一个回路是欧拉路径，该回路就是欧拉回路

    以上的前提就是，该图为连通图，一旦有不连通的点，上面条件都不可能达到

    实则就是计算机图的连通性以及每个点的度数

## 拓扑排序

该排序常常用来判断有向图是否有环

```c++
#include <iostream>
#include <cstring>
#include <queue>
#include <vector>
using namespace std;
int n, m; // 图的点数和边数
struct ty
{
  int t, next;
}edge[100010];
int cnt = 0; //边的数量
int head[1010];
void insertedge(int x, int y)
{
  edge[++cnt].t = y;
  edge[cnt].next = head[x];
  head[x] = cnt;
}
int inc[1010]; // 每个点的入度
vector<int> ans; //记录答案
queue<int> q;
// 拓扑排序
void tuopu()
{
  for (int i = 1; i <= n; i++)
  {
    //入度为0，则入队删除此点
    if (inc[i] == 0) q.push(i);
  }
  while (!q.empty())
  {
    int x = q.front();
    q.pop();
    ans.push_back(x);
    // 接下来，将所有与“删除点”有关的边全部去掉，也就是，将有与“删除点”直接连接的点的入度都减一
    for (int i = head[x]; i != -1; i = edge[i].next)
    {
      // 这些点入度减一
      inc[edge[i].t]--;
      // 发现有点入度为0，继续入队等待删除
      if (inc[edge[i].t] == 0) q.push(edge[i].t);
    }
  }
}

int main()
{
  cin >> n >> m;
  //初始化，起初所有点都是独立的，没有与其他点相连接
  memset(head, -1, sizeof(head));
  for (int i = 1; i <= m; i++)
  {
      int x, y;
      scanf("%d%d", &x, &y);
      // 记得计算点的入度
      inc[y]++;
      insertedge(x, y);
  }
  tuopu();
  // 拓扑排序结束，仍然有剩余点，意味着，剩余点必然是构成环，导致无法继续排序，输出-1
  if (ans.size() < n) cout << -1 << endl;
  else
  {
    for (auto i : ans)
    {
      cout << i << endl;
    }
  }
  return 0;
}
```

