## 一.Dijkstra（迪杰斯特拉

djs 算法常常用来解决没有负权边的图

```c++
#include <iostream>
#include <cstring>
#include <queue>
using namespace std;
struct ty
{
    int t, len, next;
}edge[200010];
int head[1010];
int vis[1010];
int dis[1010];
int cnt = 0;
struct ty1
{
    int x, dist;
    bool operator<(const ty1& a) const
    {
        return dist > a.dist;
    }
};
void addedge(int x, int y, int v)
{
    edge[++cnt].t = y;
    edge[cnt].len = v;
    edge[cnt].next = head[x];
    head[x] = cnt;
}
priority_queue<ty1> q;
int djs(int s, int t)
{
    memset(dis, 0x3f, sizeof(dis));
    memset(vis, 0, sizeof(vis));
    dis[s] = 0;
    ty1 tmp1;
    tmp1.x = s, tmp1.dist = 0;
    q.push(tmp1);
    while (!q.empty())
    {
        ty1 tmp2 = q.top();
        q.pop();
        if (vis[tmp2.x]) continue;
        vis[tmp2.x] = 1;
        for (int i = head[tmp2.x]; i != -1; i = edge[i].next)
        {
            int x = edge[i].t;
            int k = edge[i].len;
            if (k + dis[tmp2.x] < dis[x])
            {
                dis[x] = k + dis[tmp2.x];
                ty1 nex;
                nex.x = x, nex.dist = dis[x];
                q.push(nex);
            }
        }
    }
    if (dis[t] >= 0x3f3f3f3f) return -1;
    else return dis[t];
}
int main()
{
    //n 为顶点数，m 为边数， s 为起点， t 为终点
    int n, m, s, t;
    cin >> n >> m >> s >> t;
    memset(head, -1, sizeof(head));
    for (int i = 1; i <= m; i++)
    {
        int x, y, v;
        cin >> x >> y >> v;
        addedge(x, y, v);
        addedge(y, x, v);
    }
    cout << djs(s, t) << endl;
    return 0;
}
```

## 二.由 Bellman-Ford 优化后的 SPFA 算法

spfa 算法一般只有在出现了负权边的情况下才使用，因为它在极坏情况下可能退化为 o(n^3)的时间复杂度，很大概率被卡

### 如果图中出现 负环 ，此算法会出现死循环，当然反过来也就可以通过 卡循环次数 来判断图中是否含有 负环

如果同一个点被入队 n 次，即可证明图中必然存在 负环

```c++
#include <iostream>
#include <cstring>
#include <queue>
using namespace std;
struct ty
{
    int t, len, next;
}edge[200010];
int dis[1010];
int vis[1010];
int head[1010];
int cnt = 0;
void addedge(int x, int y, int v)
{
    edge[++cnt].t = y;
    edge[cnt].len = v;
    edge[cnt].next = head[x];
    head[x] = cnt;
}
queue<int> q;
int spfa(int s, int t)
{
    memset(dis, 0x3f, sizeof(dis));
    memset(vis, 0, sizeof(vis));
    dis[s] = 0;
    q.push(s);
    vis[s] = 1;
    while (!q.empty())
    {
        int tmp = q.front();
        q.pop();
        vis[tmp] = 0;
        for (int i = head[tmp]; i != -1; i = edge[i].next)
        {
            if (dis[tmp] + edge[i].len < dis[edge[i].t])
            {
                dis[edge[i].t] = dis[tmp] + edge[i].len;
                if (vis[edge[i].t] == 0)
                {
                    q.push(edge[i].t);
                    vis[edge[i].t] = 1;
                }
            }
        }
    }
    if (dis[t] >= 0x3f3f3f3f) return -1;
    else return dis[t];
}
int main()
{
    int n, m, s, t;
    cin >> n >> m >> s >> t;
    memset(head, -1, sizeof(head));
    for (int i = 1; i <= m; i++)
    {
        int x, y, v;
        cin >> x >> y >> v;
        addedge(x, y, v);
        addedge(y, x, v);
    }
    cout << spfa(s, t) << endl;
    return 0;
}
```

