```c++
#include <iostream>
using namespace std;
int a[1005];
int b[1005];
int n;
void bin(int z, int mid, int y)
{
	int q = z, p = mid + 1;
	for (int i = z; i <= y; i++)
	{
		if (p > y || (q <= mid && a[q] <= a[p]))
		{
			b[i] = a[q++];
		}
		else b[i] = a[p++];
	}
	for (int i = z; i <= y; i++)
		a[i] = b[i];
}
void sot(int z, int y)
{
	if (z == y) return;
	int mid = (y + z) / 2;
	sot(z, mid);
	sot(mid + 1, y);
	bin(z, mid, y);
}
int main()
{
