{
    return a.d < b.d;
}
int main()
{
    int n;
    cin >> n;
    for (int i = 1; i <= n; i++)
        scanf("%d%d", &a[i].c, &a[i].d);
    sort(a + 1, a + 1 + n, cmp);
    long long sum = 0, ans = 0;
    for (int i = 1; i <= n; i++)
    {
        sum += a[i].c;
