## 取余公式

    (a + b) % p = (a % p + b % p) % p
    (a - b) % p = (a % p - b % p ) % p
    (a * b) % p = (a % p * b % p) % p

## 快速幂

利用倍增思想，当求解 a 的 b 次方时，代码如下

```c++
#include <iostream>
using namespace std;
using ll = long long;
ll quik_pow(ll a, ll b)
{
  //temp存放 a^1, a^2, a^3, a^4.......
	ll temp = a;
	ll ans = 1;
	while (b)
	{
    //判断b的二进制的最后一位是否为1，是1就算入总结果
		if (b & 1) ans = ans * temp;
    //随着b的二进制右移逐渐递变
		temp = temp * temp;
    //b的二进制右移（舍弃最后一位
		b >>= 1;
	}
	return ans;
}
int main()
{
	ll a, b;
  //输入a, b,求解a的b次方
	cin >> a >> b;
	ll ans = quik_pow(a, b);
	cout << ans << endl;
	return 0;
}
```

